package com.aoo.bcg.common.cache;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.Map;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class VersionedCacheCodecTest{@Test void rejectsUnknownVersionBeforePayloadDecoderRuns(){var calls=new AtomicInteger();var codec=new VersionedCacheCodec<String>(new ObjectMapper(),Map.of(2,node->{calls.incrementAndGet();return node.get("name").asText();}));assertEquals("room",codec.decode("{\"schemaVersion\":2,\"payload\":{\"name\":\"room\"}}"));assertEquals(1,calls.get());assertThrows(IllegalStateException.class,()->codec.decode("{\"schemaVersion\":1,\"payload\":{\"name\":\"old\"}}"));assertEquals(1,calls.get());assertThrows(IllegalArgumentException.class,()->codec.decode("{\"payload\":{}}"));}}
